function buildRaw(to, subject, html) {
  const mime = [
    'From: Hector Meza <h.mezarealty@gmail.com>',
    `To: ${to}`,
    'Reply-To: hmeza@briggsfreeman.com',
    `Subject: ${subject}`,
    'MIME-Version: 1.0',
    'Content-Type: text/html; charset=UTF-8',
    '',
    html
  ].join('\r\n');
  return Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
const raw = $input.first().json;
const link = 'https://g.page/r/CabJGOEHci6qEBM/review';
let clients = [], hood = '', closing = 'bought';

if (raw.body && Array.isArray(raw.body.clients)) {
  clients = raw.body.clients; hood = (raw.body.neighborhood || '').trim();
  closing = (raw.body.closing || 'bought').toLowerCase();
} else if (raw['Client 1 first name']) {
  clients.push({ first: raw['Client 1 first name'], email: raw['Client 1 email'] });
  if (raw['Client 2 first name'] && raw['Client 2 email']) {
    clients.push({ first: raw['Client 2 first name'], email: raw['Client 2 email'] });
  }
  hood = (raw['Neighborhood'] || '').trim();
  closing = (raw['Bought or sold'] || 'bought').toLowerCase();
}
clients = clients.filter(c => c && c.first && c.email);
if (!clients.length) { throw new Error('No clients in payload'); }

return clients.map((c, i) => {
  const partner = clients.length > 1 ? clients.find((x, j) => j !== i) : null;
  const opener = closing === 'sold'
    ? `Now that everything is signed and your sale${hood ? ' in ' + hood : ''} is officially complete, I wanted to take a moment to say thank you.`
    : `Now that everything is signed and the ${hood ? 'home in ' + hood : 'home'} is officially yours, I wanted to take a moment to say thank you.`;
  const partnerNote = partner
    ? `Both reviews count on their own, so I sent ${partner.first} a separate note too. Would love to get both of your takes!`
    : '';

  const html = [
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef0f3;padding:40px 16px;">`,
    `<tr><td align="center">`,
    `<table role="presentation" width="100%" style="max-width:540px;background:#ffffff;border:1px solid #e3e2de;border-radius:10px;font-family:'Aptos','Segoe UI',Calibri,Helvetica,Arial,sans-serif;">`,
    `<tr><td style="padding:36px 40px 28px;text-align:center;border-bottom:1px solid #eeece7;">`,
    `<img src="https://hectormeza.com/hector-headshot.jpg" alt="Hector Meza" width="72" height="72" style="width:72px;height:72px;border-radius:50%;object-fit:cover;display:block;margin:0 auto 14px;border:2px solid #002349;" /><div style="font-size:20px;font-weight:700;color:#002349;">Hector Meza</div>`,
    `<div style="font-size:11px;color:#999;margin-top:6px;letter-spacing:1px;text-transform:uppercase;">Briggs Freeman Sotheby's International Realty</div>`,
    `</td></tr>`,
    `<tr><td style="padding:32px 40px 8px;font-size:15px;line-height:1.65;color:#222;">`,
    `<p style="margin:0 0 16px;">Hey ${c.first},</p>`,
    `<p style="margin:0 0 16px;">${opener} Being trusted with something this big is never lost on me, and working with you made it a genuine pleasure.</p>`,
    `<p style="margin:0 0 24px;">Can I ask you for a huge favor? Would you share a few words about your experience on Google? It takes about two minutes, and it means more than you might think. A few honest sentences from you carry more weight than anything I could say about myself.</p>`,
    `</td></tr>`,
    `<tr><td style="padding:0 40px 28px;text-align:center;">`,
    `<a href="${link}" style="display:inline-block;background:#002349;color:#ffffff;padding:13px 30px;border-radius:6px;text-decoration:none;font-weight:600;font-size:15px;">Leave a Google Review</a>`,
    `<p style="margin:16px 0 0;font-size:12px;color:#999;">Or copy this link</p>`,
    `<p style="margin:2px 0 0;font-size:12px;color:#002349;word-break:break-all;">${link}</p>`,
    `</td></tr>`,
    partnerNote ? `<tr><td style="padding:0 40px 20px;font-size:14px;color:#555;line-height:1.6;">${partnerNote}</td></tr>` : '',
    `<tr><td style="padding:0 40px 36px;font-size:15px;line-height:1.65;color:#222;">`,
    `<p style="margin:0 0 20px;">I'm here for the long haul. Contractor recommendations, market questions, or just to catch up, my door is always open. Congratulations again.</p>`,
    `<p style="margin:0;">Sincerely,<br><strong>Hector Meza</strong><br>Briggs Freeman Sotheby's International Realty<br>(214) 686-5641 &middot; <a href="https://hectormeza.com" style="color:#002349;text-decoration:none;">hectormeza.com</a></p>`,
    `</td></tr>`,
    `</table>`,
    `</td></tr>`,
    `</table>`
  ].join('');

  return { json: {
    first: c.first, email: c.email, partner: partner ? partner.first : '',
    neighborhood: hood, closing, sent_at: new Date().toISOString(),
    subject: `Congratulations again, ${c.first}`, html,
    raw: buildRaw(c.email, `Congratulations again, ${c.first}`, html)
  }};
});

